INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('japan', 'Japan', '🇯🇵', 'Asia', 'Culture,Nature', 'Neon nights, quiet temples and the art of the little details.', 'Japan is where ultra-modern cities sit next to thousand-year-old shrines. Every train is on time, every meal is a small ceremony, and every season paints the country in a different colour.', 'Late March - May (cherry blossoms) and October - November (autumn leaves)', 'https://images.unsplash.com/photo-1490806843957-31f4c9a91c65?auto=format&fit=crop&w=1600&q=75', 36.2, 138.25, 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'japan'), 'tokyo', 'Tokyo', 'A city of 14 million that still feels like a collection of small neighbourhoods, each with its own personality.', 'Tokyo has more Michelin-starred restaurants than any other city in the world - and some of them are tiny counters with fewer than 10 seats.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 1, 'Shibuya Crossing at night', 'Watch up to 3,000 people cross at once from the Shibuya Sky rooftop, then join the scramble yourself.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 2, 'Senso-ji at sunrise', 'Tokyo''s oldest temple in Asakusa, calm and golden before the crowds arrive.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 3, 'Tsukiji Outer Market breakfast', 'Tamagoyaki, fresh sushi and grilled scallops eaten standing at the stalls.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 4, 'teamLab Planets', 'Walk barefoot through water and mirrored rooms in an immersive digital art museum.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 5, 'Day trip to Mt Fuji / Hakone', 'Hot springs, a pirate ship on Lake Ashi and - on a clear day - Fuji in full view.', 'https://images.unsplash.com/photo-1490806843957-31f4c9a91c65?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=75', 'Tokyo skyline', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=1200&q=75', 'Evening lanterns', 1);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'tokyo'), 'https://images.unsplash.com/photo-1490806843957-31f4c9a91c65?auto=format&fit=crop&w=1200&q=75', 'Mt Fuji from Chureito Pagoda', 2);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'japan'), 'kyoto', 'Kyoto', 'The old imperial capital: wooden machiya houses, moss gardens and lanterns glowing in narrow lanes.', 'Kyoto has more than 1,600 Buddhist temples and about 400 Shinto shrines. It was spared from bombing in WWII because of its cultural value.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 1, 'Fushimi Inari', 'Walk the thousands of torii gates at sunrise.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 2, 'Arashiyama Bamboo Grove and Tenryu-ji', 'Towering bamboo, then a Zen garden that is a UNESCO World Heritage site.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 3, 'Gion at dusk', 'Stroll the lantern-lit streets to spot a geiko or maiko on her way to an appointment.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 4, 'Kinkaku-ji, the Golden Pavilion', 'A temple covered in gold leaf, perfectly reflected in its mirror pond.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 5, 'A tea ceremony or a kaiseki dinner', 'Slow down with matcha in a tatami room, or a multi-course seasonal feast.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=75', 'Yasaka Pagoda', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'kyoto'), 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=1200&q=75', 'Lanterns in Gion', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'japan'), 'osaka', 'Osaka', 'Japan''s kitchen: loud, friendly and obsessed with street food.', 'Osaka''s unofficial motto is "kuidaore" - eat until you drop.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka'), 1, 'Dotonbori street food crawl', 'Takoyaki, okonomiyaki and kushikatsu under the famous Glico running man sign.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka'), 2, 'Osaka Castle', 'Climb the castle for city views and walk the moats lined with cherry trees.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka'), 3, 'Kuromon Market', 'Grilled wagyu skewers and giant strawberries, straight from the stall.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka'), 4, 'Day trip to Nara', 'Bow to the friendly deer and see the giant Buddha in Todai-ji.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka'), 5, 'Umeda Sky Building at sunset', 'An open-air "floating garden" observatory 173 m above the city.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'osaka'), 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=1200&q=75', 'Osaka by night', 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'japan'), 'okinawa', 'Okinawa', 'Japan''s tropical side: turquoise water, coral reefs and a laid-back island culture.', 'Okinawa is one of the world''s "Blue Zones", with one of the highest numbers of centenarians on Earth.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa'), 1, 'Snorkel the Kerama Islands', 'Some of the clearest water in the world, with sea turtles as company.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa'), 2, 'Churaumi Aquarium', 'Whale sharks gliding past one of the largest aquarium windows anywhere.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa'), 3, 'Shuri Castle', 'The red-lacquered seat of the old Ryukyu Kingdom.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa'), 4, 'Kouri Island bridge drive', 'A two-kilometre bridge floating over turquoise shallows.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa'), 5, 'Okinawan home cooking', 'Goya champuru and purple sweet potato - the longevity diet.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'okinawa'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Okinawa coast', 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'japan'), 'hokkaido', 'Hokkaido', 'Japan''s wild north: powder snow, lavender fields and steaming hot springs.', 'Hokkaido''s Niseko gets around 15 metres of snow a season - some of the lightest powder on the planet.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1600&q=75', 4);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido'), 1, 'Ski or snowboard Niseko', 'World-famous powder with Mt Yotei rising behind the slopes.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido'), 2, 'Sapporo Snow Festival', 'Giant ice sculptures every February.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido'), 3, 'Furano lavender fields', 'Purple hills from late June to early August.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido'), 4, 'Onsen in Noboribetsu', 'Soak in sulphur springs next to the steaming "Hell Valley".', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido'), 5, 'Fresh seafood in Otaru', 'Uni, crab and salmon roe bowls in a canal-side harbour town.', 'https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'japan' AND p.slug = 'hokkaido'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Hokkaido in winter', 0);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('iceland', 'Iceland', '🇮🇸', 'Europe', 'Nature', 'Fire, ice and the Northern Lights dancing overhead.', 'Iceland feels like another planet: black-sand beaches, glaciers, geysers and waterfalls around every bend of the Ring Road. In summer the sun barely sets; in winter the sky lights up green.', 'June - August (midnight sun, road trips) and September - March (Northern Lights)', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=1600&q=75', 64.96, -19.02, 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'iceland'), 'reykjavik', 'Reykjavik', 'The world''s northernmost capital: colourful houses, cosy cafes and a big creative scene.', 'Reykjavik runs almost entirely on renewable geothermal and hydro energy - even some pavements are heated to melt the snow.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 1, 'Hallgrimskirkja tower', 'Ride up the basalt-inspired church for a view over the rainbow rooftops.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 2, 'Sky Lagoon at sunset', 'An infinity-edge geothermal pool looking out over the ocean.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 3, 'Harpa concert hall', 'A glass honeycomb on the harbour that glows at night.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 4, 'Whale watching from the Old Harbour', 'Minke whales, humpbacks and puffins in summer.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 5, 'Northern Lights hunt', 'Drive out of the city lights on a clear winter night.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=1200&q=75', 'Reykjavik rooftops', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'reykjavik'), 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1200&q=75', 'Aurora over the bay', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'iceland'), 'golden-circle', 'Golden Circle', 'A 300 km loop with three of Iceland''s most famous natural wonders.', 'At Thingvellir you can snorkel in Silfra, a crack between the North American and Eurasian tectonic plates.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle'), 1, 'Snorkel Silfra fissure', 'Glacier water so clear you can see over 100 m - between two continents.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle'), 2, 'Strokkur geyser', 'Erupts every 5 - 10 minutes, shooting water up to 30 m high.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle'), 3, 'Gullfoss waterfall', 'A two-step thundering waterfall, often with a rainbow.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle'), 4, 'Secret Lagoon', 'Iceland''s oldest natural swimming pool, steaming in the fields.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle'), 5, 'Kerid crater', 'A red volcanic crater with a blue-green lake at its bottom.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'golden-circle'), 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=1200&q=75', 'Golden Circle landscapes', 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'iceland'), 'south-coast', 'South Coast (Vik)', 'Waterfalls, glaciers and black-sand beaches along the Ring Road.', 'Reynisfjara''s black sand comes from lava that cooled instantly when it hit the cold Atlantic.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast'), 1, 'Walk behind Seljalandsfoss', 'A path circles right behind the curtain of water.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast'), 2, 'Skogafoss', 'Climb the 500+ steps for the view from the top.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'south-coast'), 3, 'Reynisfjara black-sand beach', 'Basalt columns and sea stacks - but respect the sneaker waves.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=800&q=75');
