INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'iceland'), 'snaefellsnes', 'Snaefellsnes', 'Called "Iceland in miniature" - a peninsula with a bit of everything.', 'Jules Verne chose the Snaefellsjokull glacier as the entrance in "Journey to the Center of the Earth".', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes'), 1, 'Kirkjufell mountain', 'The most photographed mountain in Iceland, with waterfalls in front.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes'), 2, 'Arnarstapi cliffs', 'A coastal walk past basalt arches and nesting birds.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes'), 3, 'Budir black church', 'A lonely black church in a lava field.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes'), 4, 'Vatnshellir lava cave', 'Descend 35 m into an 8,000-year-old lava tube.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'snaefellsnes'), 5, 'Djupalonssandur beach', 'Black pebbles and shipwreck remains on a wild shore.', 'https://images.unsplash.com/photo-1476610182048-b716b8518aae?auto=format&fit=crop&w=800&q=75');
