INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'iceland'), 'akureyri', 'North (Akureyri)', 'The capital of the north and the gateway to Lake Myvatn and whale country.', 'Akureyri''s traffic lights have heart-shaped red lights - a small campaign to cheer people up after the 2008 crisis.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1600&q=75', 4);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri'), 1, 'Whale watching in Husavik', 'The whale-watching capital of Europe.', 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri'), 2, 'Lake Myvatn', 'Pseudo-craters, lava formations and bubbling mud pots.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'iceland' AND p.slug = 'akureyri'), 3, 'Myvatn Nature Baths', 'The quieter, milky-blue cousin of the Blue Lagoon.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
