INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('morocco', 'Morocco', '🇲🇦', 'Africa', 'Culture,Nature', 'Spice markets, blue lanes and nights under the Sahara stars.', 'Morocco is a feast for the senses: the call to prayer over the medina, mint tea poured from a height, riads hidden behind plain doors and dunes that glow orange at sunset.', 'March - May and September - November (mild, not too hot in the desert)', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=1600&q=75', 31.79, -7.09, 2);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'morocco'), 'marrakech', 'Marrakech', 'The Red City: busy souks, palaces and rooftop sunsets.', 'Every evening Jemaa el-Fnaa square turns into an open-air food court with storytellers, musicians and over 100 food stalls - a UNESCO "Masterpiece of Intangible Heritage".', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 1, 'Jemaa el-Fnaa at dusk', 'Watch the square transform from a rooftop cafe, then dive into the food stalls.', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 2, 'Jardin Majorelle', 'Cobalt-blue villa and cactus garden once owned by Yves Saint Laurent.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 3, 'Get lost in the souks', 'Leather, lanterns, spices - and the art of friendly haggling.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 4, 'Stay in a riad + hammam', 'A courtyard house with a fountain, and a traditional steam scrub.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 5, 'Day trip to the Atlas Mountains', 'Berber villages, waterfalls and lunch with a view.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=1200&q=75', 'Marrakech medina', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'marrakech'), 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=1200&q=75', 'Riad courtyard', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'morocco'), 'fes', 'Fes', 'The cultural heart of Morocco and its oldest imperial city.', 'Fes el-Bali is the largest car-free urban area in the world - goods are still carried by donkey through its 9,000+ alleys.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes'), 1, 'Chouara tannery', 'See leather dyed in stone vats the same way as 900 years ago.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes'), 2, 'Al-Qarawiyyin', 'Founded in 859, considered the oldest existing university in the world.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes'), 3, 'Bou Inania Madrasa', 'Carved cedar, zellige tiles and stucco - a masterpiece of Marinid art.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes'), 4, 'Guided medina walk', 'A local guide is the best way to find hidden workshops.', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes'), 5, 'Sunset from the Merenid Tombs', 'The whole medina glows below you.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'fes'), 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=1200&q=75', 'Fes', 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'morocco'), 'chefchaouen', 'Chefchaouen', 'The famous blue pearl in the Rif Mountains.', 'Nobody agrees why the town is blue - theories include keeping mosquitoes away, staying cool, or symbolising the sky and heaven.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen'), 1, 'Photograph the blue lanes', 'Go early morning for empty streets and soft light.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen'), 2, 'Spanish Mosque viewpoint', 'A short hike for sunset over the whole blue town.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen'), 3, 'Akchour waterfalls', 'Turquoise pools and the "God''s Bridge" rock arch.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen'), 4, 'Plaza Uta el-Hammam', 'Mint tea and goat cheese in the main square.', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen'), 5, 'Ras el-Maa spring', 'Where locals still wash wool and clothes in the mountain stream.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'chefchaouen'), 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=1200&q=75', 'Blue lanes', 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'morocco'), 'sahara', 'Sahara (Merzouga)', 'The Erg Chebbi dunes - up to 150 m high and glowing orange at sunset.', 'The Sahara is roughly the size of the USA, but only about a quarter of it is sand dunes - the rest is rocky plateaus and gravel plains.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara'), 1, 'Camel trek at sunset', 'Ride into the dunes as they turn from gold to deep orange.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'sahara'), 2, 'Night in a desert camp', 'Berber drums by the fire and more stars than you''ve ever seen.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
