INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'morocco'), 'essaouira', 'Essaouira', 'A breezy, whitewashed port town on the Atlantic.', 'Essaouira''s walls were a filming location for Astapor in "Game of Thrones".', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 4);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira'), 1, 'Skala de la Ville ramparts', 'Old cannons and crashing waves at sunset.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira'), 2, 'Grilled fish at the port', 'Pick it from the stall, they grill it in front of you.', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'morocco' AND p.slug = 'essaouira'), 3, 'Kitesurfing', 'The trade winds make it one of Africa''s best kite spots.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
