INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('thailand', 'Thailand', '🇹🇭', 'Asia', 'Beach,Culture', 'Golden temples, island hopping and the best street food on Earth.', 'From the buzz of Bangkok to the jungles and temples of the north and the limestone islands of the south. Thailand is the Land of Smiles: night markets, long-tail boats, mango sticky rice and some of the most beautiful beaches in Asia.', 'November - April (dry season on the Andaman coast: Phuket, Krabi, Phi Phi); November - February is the coolest', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=1600&q=75', 15.87, 100.99, 3);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'thailand'), 'bangkok', 'Bangkok', 'A non-stop capital of golden temples, river boats, rooftop bars and street food on every corner.', 'Bangkok''s full ceremonial name, starting with "Krung Thep Maha Nakhon", is the longest place name in the world - Thais simply call the city Krung Thep, the "City of Angels".', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 1, 'Grand Palace and Wat Phra Kaew', 'The dazzling former royal residence and the temple of the Emerald Buddha. Cover your shoulders and knees.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 2, 'Wat Pho and Wat Arun', 'See the 46 m Reclining Buddha, then take the ferry across the river to Wat Arun for sunset.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 3, 'Chinatown street food at night', 'Yaowarat Road lights up with neon signs and stalls selling noodles, seafood and mango sticky rice.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 4, 'Long-tail boat through the canals', 'Explore the khlongs of Thonburi and see wooden stilt houses and the old side of the city.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 5, 'Chatuchak Weekend Market', 'One of the largest markets in the world, with thousands of stalls - go early, it gets hot.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=1200&q=75', 'Temples of Bangkok', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'bangkok'), 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=75', 'City streets', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'thailand'), 'chiang-mai', 'Chiang Mai', 'The relaxed capital of the north: an old walled city, mountain temples and cooking classes.', 'Chiang Mai has more than 300 Buddhist temples - almost as many as Bangkok, in a city a fraction of the size.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 1, 'Wat Phra That Doi Suthep', 'Climb the naga staircase of about 300 steps to the golden mountain temple, with views over the city.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 2, 'An ethical elephant sanctuary', 'Feed and walk with rescued elephants at a sanctuary that does not offer riding.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 3, 'Thai cooking class', 'Shop at a local market, then cook your own curry paste, pad thai and mango sticky rice.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 4, 'Old City temples by bike', 'Cycle between Wat Chedi Luang, Wat Phra Singh and the quiet temples inside the old moat.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 5, 'Sunday Walking Street market', 'Handicrafts, khao soi noodles and live music along Ratchadamnoen Road every Sunday evening.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Northern mountains', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'chiang-mai'), 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=1200&q=75', 'Temple details', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'thailand'), 'phuket', 'Phuket', 'Thailand''s largest island: long sandy beaches, a colourful old town and boat trips to Phang Nga Bay.', 'Phuket grew rich from tin mining, which brought Chinese and European traders - that is why its Old Town is full of colourful Sino-Portuguese shophouses.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 1, 'Phang Nga Bay and James Bond Island', 'Limestone towers rising out of emerald water, made famous by "The Man with the Golden Gun".', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 2, 'Phuket Old Town', 'Pastel shophouses, street art and cafes on Thalang Road, plus a night market on Sundays.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 3, 'The Big Buddha', 'A 45 m white marble Buddha on a hilltop, with views over Chalong Bay.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 4, 'Sunset at Promthep Cape', 'The southern tip of the island, where everyone gathers to watch the sun drop into the sea.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 5, 'Dive or snorkel the Similan Islands', 'Granite boulders and some of the clearest water in Thailand (the park opens roughly October to May).', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Andaman coast', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phuket'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Phang Nga Bay', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'thailand'), 'krabi', 'Krabi', 'Dramatic limestone cliffs, hidden lagoons and some of the best rock climbing in the world.', 'Railay is on the mainland, but it is cut off by tall limestone cliffs - the only way to get there is by boat.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 1, 'Railay Beach and Phra Nang Cave', 'White sand framed by towering cliffs, and a cave beach full of offerings to the local sea goddess.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 2, 'Four Islands tour by long-tail boat', 'Hop between Poda, Chicken Island and Tup Island, where a sandbar appears at low tide.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 3, 'Rock climbing in Railay', 'Beginner-friendly courses on limestone walls right above the beach.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 4, 'Tiger Cave Temple', 'More than 1,200 steep steps to a golden Buddha at the top, with jungle views all around. Go early.', 'https://images.unsplash.com/photo-1528181304800-259b08848526?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 5, 'Emerald Pool and the hot springs', 'A turquoise pool in the forest, then a warm waterfall soak at Khlong Thom.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Limestone cliffs', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'krabi'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Island hopping', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'thailand'), 'phi-phi-islands', 'Phi Phi Islands', 'Turquoise lagoons, white beaches and cliffs straight out of a movie, a short ferry ride from Phuket or Krabi.', 'Maya Bay, where "The Beach" with Leonardo DiCaprio was filmed, was closed from 2018 to 2022 so the coral could recover - and blacktip reef sharks came back to the bay.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1600&q=75', 4);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 1, 'Maya Bay early in the morning', 'See the famous bay before the day trips arrive. Swimming is not allowed and it closes for part of each year.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 2, 'Hike to the Phi Phi Viewpoint', 'A sweaty climb for the classic view of the two curved bays of Phi Phi Don, best at sunset.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 3, 'Snorkel Pileh Lagoon and Bamboo Island', 'Swim in an emerald lagoon surrounded by cliffs, then relax on a quiet white-sand island.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 4, 'Kayak to Monkey Beach', 'Paddle along the cliffs to a small beach (watch your bags and do not feed the monkeys).', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 5, 'Sunset and fire shows on Loh Dalum', 'Beach bars and fire dancers after dark - there are no cars on the island, so you walk everywhere.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Turquoise lagoon', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'thailand' AND p.slug = 'phi-phi-islands'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Phi Phi coastline', 1);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('bali', 'Bali', '🇮🇩', 'Islands', 'Beach,Culture,Nature', 'Rice terraces, temple ceremonies and surf at sunset.', 'The Island of the Gods, in Indonesia: spiritual, green and endlessly photogenic. Small offerings of flowers sit on every doorstep, temple ceremonies fill the streets with music, and in one day you can go from jungle waterfalls to clifftop sunsets.', 'April - October (dry season); May, June and September have fewer crowds than July - August', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1600&q=75', -8.34, 115.09, 4);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'bali'), 'ubud', 'Ubud', 'Bali''s cultural heart in the jungle: rice terraces, yoga, craft villages and traditional dance.', 'The Balinese rice terraces are watered by "subak", a cooperative irrigation system run by water temples since the 9th century. It is a UNESCO World Heritage site.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 1, 'Tegallalang Rice Terraces at sunrise', 'Walk the green steps before the heat and the crowds - and try the famous jungle swing if you like.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 2, 'Sacred Monkey Forest Sanctuary', 'Moss-covered temples and hundreds of long-tailed macaques. Hide sunglasses and snacks.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 3, 'Campuhan Ridge Walk', 'An easy path along a grassy ridge between two river valleys, lovely at sunrise or sunset.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 4, 'Tirta Empul water temple', 'Join the Balinese in a purification ritual under the holy springs. Sarongs are provided.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 5, 'Kecak or Legong dance at night', 'Traditional dance at the Ubud Palace or a local temple, lit by fire and lanterns.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=75', 'Rice terraces', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'ubud'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Ubud jungle', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'bali'), 'uluwatu', 'Uluwatu', 'The wild southern tip of Bali: limestone cliffs, hidden beaches and world-class surf.', 'Pura Luhur Uluwatu, perched about 70 m above the ocean, is one of Bali''s six key temples that are believed to protect the island from evil spirits.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 1, 'Uluwatu Temple and the Kecak fire dance', 'A clifftop temple at sunset, followed by the hypnotic chanting dance. Watch out for the monkeys.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 2, 'Padang Padang and Bingin beaches', 'Small coves reached by steps through the cliffs, with golden sand and clear water.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 3, 'Watch or learn to surf', 'Some of the most famous reef breaks in the world - beginners can take lessons on gentler beaches.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 4, 'Melasti Beach', 'A road carved through white cliffs leads down to a wide beach with turquoise water.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 5, 'Sunset at a clifftop beach club', 'Cocktails and an infinity pool above the Indian Ocean.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Uluwatu cliffs', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'uluwatu'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Indian Ocean', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'bali'), 'canggu-seminyak', 'Canggu & Seminyak', 'Bali''s trendy west coast: surf beaches, cafes, boutiques and the best sunsets on the island.', 'Canggu was a quiet area of rice fields and a few surf spots until the 2010s - today it is one of the most popular places in the world for digital nomads.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 1, 'Tanah Lot at sunset', 'A sea temple on a rock in the ocean - at low tide you can walk to its base.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 2, 'Surf lesson at Batu Bolong', 'Soft, rolling waves that are perfect for your first time on a board.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 3, 'Cafe and brunch hopping', 'Smoothie bowls, great coffee and healthy food on every street.', 'https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 4, 'Seminyak boutiques and spas', 'Shop local designers, then book a traditional Balinese massage.', 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 5, 'Sunset at Echo Beach or a beach club', 'Bean bags on the sand and live music as the sky turns orange.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=1200&q=75', 'Sunset on the west coast', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'canggu-seminyak'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Surf beach', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'bali'), 'nusa-penida', 'Nusa Penida', 'A rugged island a short fast-boat ride from Bali, famous for its dramatic cliffs and manta rays.', 'Kelingking Beach is nicknamed "T-Rex Bay" because, seen from above, the cliff looks like the head of a Tyrannosaurus.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 1, 'Kelingking Beach viewpoint', 'The famous T-Rex cliff. The path down to the beach is very steep - only go with good shoes.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 2, 'Snorkel with manta rays', 'Swim with giant mantas at Manta Point or Manta Bay on a boat trip.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 3, 'Broken Beach and Angel''s Billabong', 'A natural rock arch over a circular bay, and a clear rock pool next to it (check the waves first).', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 4, 'Diamond Beach', 'Steps carved into the cliff lead to white sand and blue water on the east coast.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 5, 'Sunrise at the Thousand Islands viewpoint', 'A row of small islands below the cliffs, golden in the morning light.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Nusa Penida cliffs', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'bali' AND p.slug = 'nusa-penida'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Manta rays waters', 1);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('malaysia', 'Malaysia', '🇲🇾', 'Asia', 'Culture,Nature,Beach', 'Skyscrapers, rainforest and a food scene shaped by three cultures.', 'Malay, Chinese and Indian flavours meet in cities, islands and one of the oldest rainforests in the world. One week you can eat your way through hawker stalls under the Petronas Towers, the next you can watch wild orangutans in Borneo.', 'December - April for the west coast (Penang, Langkawi); March - October for Sabah (Borneo); Kuala Lumpur is good all year', 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=1600&q=75', 4.21, 101.98, 5);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'malaysia'), 'kuala-lumpur', 'Kuala Lumpur', 'A modern skyline, colourful temples and some of the best street food in Asia.', 'At 452 m, the Petronas Twin Towers were the tallest buildings in the world from 1998 to 2004, and they are still the tallest twin towers on Earth.', 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 1, 'Petronas Twin Towers and the Skybridge', 'Walk the bridge between the towers, then see them light up from KLCC Park at night. Book tickets ahead.', 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 2, 'Batu Caves', 'Climb the 272 rainbow-coloured steps to a Hindu temple inside a huge limestone cave, guarded by a giant golden statue.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 3, 'Jalan Alor food street', 'Satay, chilli crab and durian at hundreds of open-air stalls every evening.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 4, 'Merdeka Square and the old town', 'The place where independence was declared in 1957, surrounded by Moorish-style buildings.', 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 5, 'KL Tower or a rooftop bar at sunset', 'See the whole skyline turn gold, then sparkle as the city lights come on.', 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=1200&q=75', 'Kuala Lumpur skyline', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'kuala-lumpur'), 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=75', 'Street food at night', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'malaysia'), 'penang', 'Penang', 'An island famous for George Town''s heritage streets, street art and legendary hawker food.', 'George Town''s famous murals were started in 2012 by Lithuanian artist Ernest Zacharevic for a festival. They were meant to be temporary, and now they are the city''s biggest attraction.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 1, 'George Town street art hunt', 'Find the murals and iron caricatures around the UNESCO-listed old town - on foot or by bike.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 2, 'Hawker food crawl', 'Char kway teow, assam laksa and cendol at Gurney Drive or New Lane - Penang is Malaysia''s food capital.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 3, 'Kek Lok Si Temple', 'One of the largest Buddhist temples in Southeast Asia, beautifully lit with lanterns at night.', 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 4, 'Penang Hill by funicular', 'Ride up the hill for cooler air and a view over George Town and the bridge to the mainland.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 5, 'Chew Jetty, the clan jetties', 'Wooden houses on stilts over the water, still home to Chinese clan families.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=75', 'George Town streets', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'penang'), 'https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=1200&q=75', 'Temples of Penang', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'malaysia'), 'langkawi', 'Langkawi', 'A relaxed tropical archipelago of rainforest, mangroves and quiet beaches.', 'Langkawi is a group of 99 islands - a few more appear at low tide. The whole archipelago is a UNESCO Global Geopark and a duty-free zone.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 1, 'SkyCab and the Sky Bridge', 'A steep cable car ride up Mount Mat Cincang to a curved bridge hanging over the rainforest.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 2, 'Kilim mangrove boat or kayak tour', 'Glide through mangroves and limestone caves, with eagles circling overhead.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 3, 'Island hopping', 'Swim in the Lake of the Pregnant Maiden on Dayang Bunting and relax on Beras Basah beach.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 4, 'Seven Wells Waterfall', 'A jungle hike to natural rock pools stacked one above the other.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 5, 'Sunset at Pantai Cenang', 'The island''s liveliest beach, with seafood dinners on the sand.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Langkawi beaches', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'langkawi'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Mangroves', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'malaysia'), 'borneo-sabah', 'Borneo (Sabah)', 'Wild Borneo: orangutans, rainforest rivers, Mount Kinabalu and some of the best diving in the world.', 'Borneo is the third-largest island in the world and the only one shared by three countries: Malaysia, Indonesia and Brunei.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 1, 'Sepilok Orangutan Rehabilitation Centre', 'Watch rescued orangutans swing in for feeding time in the rainforest.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 2, 'Kinabatangan River cruise', 'Look out for proboscis monkeys, hornbills and even pygmy elephants at dawn and dusk.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 3, 'Climb or visit Mount Kinabalu', 'Malaysia''s highest peak at 4,095 m - a two-day climb, or easy nature trails in Kinabalu Park.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 4, 'Dive or snorkel at Sipadan', 'Turtles, barracuda tornadoes and reef sharks. Daily permits are limited, so book early.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 5, 'Island hopping from Kota Kinabalu', 'Snorkel in Tunku Abdul Rahman Park, then catch sunset and the night market in the city.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Mount Kinabalu', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'malaysia' AND p.slug = 'borneo-sabah'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Borneo rainforest', 1);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('singapore', 'Singapore', '🇸🇬', 'Asia', 'Culture', 'A garden city of the future, with hawker food from the past.', 'Tiny, spotless and surprisingly green, with neighbourhoods that each feel like a different country.', 'February - April (less rain)', 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1600&q=75', 1.35, 103.82, 6);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'singapore'), 'marina-bay', 'Marina Bay', NULL, NULL, 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'singapore'), 'sentosa', 'Sentosa', NULL, NULL, 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'singapore'), 'chinatown-little-india', 'Chinatown & Little India', NULL, NULL, 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'singapore'), 'gardens-nature', 'Gardens & Nature', NULL, NULL, 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('hawaii', 'Hawaii', '🌺', 'Islands', 'Beach,Nature', 'Volcanoes, rainbows and the true spirit of aloha.', 'A US state in the middle of the Pacific, more than 3,000 km from the nearest continent. Every island has its own personality: Oahu buzzes, Maui relaxes, the Big Island is still being built by lava and Kauai is pure green jungle.', 'April - May and September - October (dry, fewer crowds, better prices); December - April for humpback whales', 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=1600&q=75', 20.8, -156.33, 7);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'hawaii'), 'oahu', 'Oahu', 'The Gathering Place: Honolulu city life, Waikiki beach and legendary surf on the North Shore.', 'Iolani Palace in Honolulu is the only royal palace on US soil - it was home to the last Hawaiian monarchs and had electric light before the White House did.', 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 1, 'Diamond Head at sunrise', 'A short, steep hike up an old volcanic crater for a view over Waikiki and the ocean. Book your entry slot ahead.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 2, 'Pearl Harbor and the USS Arizona Memorial', 'A quiet, moving visit to the place that pulled the US into World War II.', 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 3, 'North Shore day', 'Watch the big-wave surfers in winter, then garlic shrimp from a Haleiwa food truck.', 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 4, 'Snorkel Hanauma Bay', 'A protected bay inside a volcanic cone, full of reef fish and green sea turtles. Reservations required.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 5, 'Kualoa Ranch', 'The dramatic green valley where Jurassic Park and Jumanji were filmed - by jeep, horse or e-bike.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=1200&q=75', 'Oahu coastline', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'oahu'), 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=1200&q=75', 'Turquoise water', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'hawaii'), 'maui', 'Maui', 'The Valley Isle: sunrise above the clouds, winding coastal roads and whales in winter.', 'Haleakala means "House of the Sun". Legend says the demigod Maui lassoed the sun from its summit to make the days longer.', 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 1, 'Sunrise at Haleakala', 'Watch the sun rise above a sea of clouds from 3,000 m. Sunrise entry must be reserved in advance - bring a jacket.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 2, 'Road to Hana', 'Hundreds of curves, one-lane bridges, waterfalls, black-sand beaches and banana bread stands.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 3, 'Snorkel Molokini Crater', 'A half-sunken volcanic crater with some of the clearest water in Hawaii.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 4, 'Whale watching (December - April)', 'Thousands of humpback whales come to Maui''s warm waters to give birth.', 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 5, 'Kaanapali Beach and Black Rock', 'Snorkel with turtles at Black Rock, then stay for the cliff-diving ceremony at sunset.', 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=1200&q=75', 'Maui beach', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'maui'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Above the clouds', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'hawaii'), 'big-island', 'Big Island', 'The youngest and largest island, where active volcanoes are still adding new land.', 'Measured from its base on the ocean floor, Mauna Kea is over 10,000 m tall - higher than Mount Everest.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 1, 'Hawaii Volcanoes National Park', 'Walk past steaming vents and craters around Kilauea - at night, check if the lava glow is visible.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 2, 'Manta ray night snorkel in Kona', 'Float at the surface while giant mantas do somersaults in the lights below you.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 3, 'Stargazing on Mauna Kea', 'One of the best places on Earth to see the stars, home to world-class observatories.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 4, 'Punaluu Black Sand Beach', 'Jet-black volcanic sand with green sea turtles resting on the shore (keep your distance).', 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 5, 'Kona coffee farm tour', 'Taste some of the world''s most famous coffee right where it grows on the volcano slopes.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Volcanic landscape', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'big-island'), 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1200&q=75', 'Night sky', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'hawaii'), 'kauai', 'Kauai', 'The Garden Isle: the oldest main island, all emerald cliffs, waterfalls and quiet beaches.', 'On Kauai no building can be taller than a coconut tree - a local rule that keeps the island wild and low-rise.', 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 1, 'Na Pali Coast by boat or helicopter', 'Sheer green cliffs dropping into the ocean, only reachable by sea, air or a long hike.', 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 2, 'Waimea Canyon', 'Nicknamed the "Grand Canyon of the Pacific" - red rock, green ridges and waterfalls.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 3, 'Hanalei Bay', 'A wide crescent of sand with mountains behind it. Perfect for a lazy beach day or paddleboarding.', 'https://images.unsplash.com/photo-1507876466758-bc54f384809c?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 4, 'Kalalau Trail to Hanakapiai', 'The first part of the famous coastal trail. Reserve Haena State Park entry in advance.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 5, 'Kayak the Wailua River', 'Paddle through the jungle, then hike to a waterfall for a swim.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 'https://images.unsplash.com/photo-1542259009477-d625272157b7?auto=format&fit=crop&w=1200&q=75', 'Na Pali Coast', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'hawaii' AND p.slug = 'kauai'), 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=75', 'Waimea Canyon', 1);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('egypt', 'Egypt', '🇪🇬', 'Africa', 'Culture,Beach', 'Pharaohs, the Nile and coral reefs in the Red Sea.', '5,000 years of history along the Nile, plus some of the best diving in the world. Stand in front of the last surviving Wonder of the Ancient World, sail a felucca at sunset, walk into painted tombs in the Valley of the Kings and then swim with turtles in the Red Sea.', 'October - April (cooler for temples and the desert); the Red Sea is good all year. Around 22 February and 22 October the sun lights up the inner sanctuary of Abu Simbel', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=1600&q=75', 26.82, 30.8, 8);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'egypt'), 'cairo-giza', 'Cairo & Giza', 'A huge, loud, fascinating capital, with the Pyramids of Giza waiting at the edge of the desert.', 'The Great Pyramid of Giza was the tallest man-made structure on Earth for about 3,800 years, and it is the only one of the Seven Wonders of the Ancient World still standing.', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 1, 'The Pyramids and the Sphinx at opening time', 'Arrive early to beat the heat and the crowds, and head to the panorama point for the classic view of all nine pyramids.', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 2, 'Grand Egyptian Museum', 'The huge new museum next to the pyramids, home to the full treasure of Tutankhamun. Plan at least half a day.', 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 3, 'Saqqara and the Step Pyramid of Djoser', 'The oldest pyramid in Egypt, plus beautifully painted tombs with far fewer visitors than Giza.', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 4, 'Khan el-Khalili and Islamic Cairo', 'Get lost in the old bazaar, then have mint tea at El Fishawy, a cafe open for more than 200 years.', 'https://images.unsplash.com/photo-1539020140153-e479b8c22e70?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 5, 'Felucca on the Nile at sunset', 'A traditional wooden sailboat, the city lights coming on along both banks.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=1200&q=75', 'Pyramids of Giza', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'cairo-giza'), 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=1200&q=75', 'Ancient Egypt', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'egypt'), 'luxor', 'Luxor', 'Ancient Thebes, often called the world''s greatest open-air museum: temples on the east bank, royal tombs on the west.', 'Tutankhamun''s tomb in the Valley of the Kings was found almost untouched by Howard Carter in 1922 - his mummy still rests there today.', 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 1, 'Hot-air balloon at sunrise', 'Float above the West Bank temples, the green fields of the Nile and the desert mountains.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 2, 'Valley of the Kings', 'Walk into colourful royal tombs carved deep into the rock. Extra tickets are needed for the most famous ones.', 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 3, 'Karnak Temple', 'One of the largest religious complexes ever built - the Great Hypostyle Hall has 134 giant columns.', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 4, 'Luxor Temple at night', 'The temple and its Avenue of Sphinxes, beautifully lit after sunset.', 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 5, 'Temple of Hatshepsut and the Colossi of Memnon', 'The terraced temple of one of Egypt''s few female pharaohs, and two 18 m stone giants on the way.', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=1200&q=75', 'Temples of Luxor', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'luxor'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Sunrise over the West Bank', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'egypt'), 'aswan', 'Aswan', 'The calmest place on the Nile: granite islands, colourful Nubian villages and the gateway to Abu Simbel.', 'In the 1960s the temples of Abu Simbel were cut into blocks and moved 65 m higher, piece by piece, to save them from the rising waters of Lake Nasser.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 1, 'Day trip to Abu Simbel', 'Ramses II''s colossal temples near the Sudan border. An early start, but completely worth it.', 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 2, 'Philae Temple', 'The island temple of Isis, reached by a small boat - also rescued and moved from the rising Nile.', 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 3, 'Felucca around Elephantine Island', 'Sail past granite boulders and Kitchener''s Botanical Island in the late afternoon light.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 4, 'Visit a Nubian village', 'Brightly painted houses, henna, spices and a warm welcome on the West Bank.', 'https://images.unsplash.com/photo-1553603227-2358aabe821e?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 5, 'Nile cruise to Luxor', 'Three or four slow days on the river, stopping at the temples of Kom Ombo and Edfu.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'The Nile at Aswan', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'aswan'), 'https://images.unsplash.com/photo-1539650116574-8efeb43e2750?auto=format&fit=crop&w=1200&q=75', 'Abu Simbel', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'egypt'), 'red-sea-hurghada', 'Red Sea', 'Warm, clear water and colourful coral reefs along the coast of Hurghada, El Gouna and Marsa Alam.', 'The Red Sea is one of the saltiest seas in the world, and it is home to more than 1,000 species of fish - many of them found nowhere else on Earth.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 1, 'Snorkel the Giftun Islands', 'A boat trip from Hurghada to white-sand islands and shallow coral gardens.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 2, 'Swim with turtles in Marsa Alam', 'At Abu Dabbab bay green sea turtles feed on the seagrass close to the beach - and sometimes a dugong too.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 3, 'Dive the SS Thistlegorm', 'A World War II cargo ship full of motorbikes and trucks, one of the most famous wreck dives in the world (for certified divers).', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 4, 'Desert safari and a Bedouin dinner', 'Quad bikes or jeeps into the mountains, then dinner and stargazing in the desert.', 'https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 5, 'Kitesurf or relax in El Gouna', 'A car-free lagoon town with steady winds, boat taxis and waterfront restaurants.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Red Sea coast', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'egypt' AND p.slug = 'red-sea-hurghada'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Coral reef waters', 1);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('italy', 'Italy', '🇮🇹', 'Europe', 'Nature,Beach,Culture', 'Jagged peaks in the north, turquoise coves in the south, and history on every corner.', 'La dolce vita in every form: hiking under the pink peaks of the Dolomites, swimming in the Caribbean-blue coves of Sardinia, eating orecchiette in the old lanes of Bari, walking through 2,000 years of history in Rome and, of course, holding up the Leaning Tower of Pisa.', 'May - June and September - October for cities and the coast (warm, fewer crowds); late June - September for Dolomites hiking; December - March for skiing', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1600&q=75', 41.87, 12.57, 9);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'italy'), 'dolomites', 'Dolomites', 'Pale limestone peaks, alpine meadows and mountain huts serving strudel and polenta in the north of Italy.', 'At sunset the Dolomites often glow pink and orange - locals call it "enrosadira". The rock contains dolomite, a mineral named after the French geologist Deodat de Dolomieu.', 'https://images.unsplash.com/photo-1531219432768-9f540ce91ef3?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 1, 'Tre Cime di Lavaredo loop', 'A classic half-day hike around the three famous peaks, starting from Rifugio Auronzo (toll road, go early).', 'https://images.unsplash.com/photo-1531219432768-9f540ce91ef3?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 2, 'Lago di Braies at sunrise', 'An emerald lake under steep cliffs - rent a wooden rowing boat before the crowds arrive.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 3, 'Seceda ridgeline', 'Take the cable car from Ortisei to one of the most dramatic ridges in the Alps.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 4, 'Alpe di Siusi', 'Europe''s largest high-altitude meadow, perfect for easy walks, cycling or skiing in winter.', 'https://images.unsplash.com/photo-1531219432768-9f540ce91ef3?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 5, 'Lunch at a rifugio', 'Mountain huts with sunny terraces, canederli dumplings and apple strudel with a view.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 'https://images.unsplash.com/photo-1531219432768-9f540ce91ef3?auto=format&fit=crop&w=1200&q=75', 'Dolomites peaks', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'dolomites'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Alpine lake', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'italy'), 'sardinia', 'Sardinia', 'An island of turquoise coves, white sand and ancient stone towers in the middle of the Mediterranean.', 'Sardinia has more than 7,000 nuraghi - mysterious stone towers built over 3,000 years ago. It is also one of the world''s "Blue Zones", where many people live past 100.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 1, 'Boat trip in the Gulf of Orosei', 'Hidden coves like Cala Goloritze and Cala Mariolu, only reachable by boat or a steep hike.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 2, 'La Pelosa beach', 'Shallow, crystal-clear water near Stintino. Book your entry ahead in summer and bring a beach mat - towels are not allowed.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 3, 'La Maddalena archipelago', 'Sail between pink-granite islands with some of the clearest water in the Mediterranean.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 4, 'Su Nuraxi di Barumini', 'The best-preserved nuraghe village on the island, a UNESCO World Heritage site.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 5, 'Sunset in Alghero', 'Walk the old sea walls of this Catalan-flavoured town, then dinner with local seafood.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Sardinian coast', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'sardinia'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'Turquoise coves', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'italy'), 'bari', 'Bari', 'The lively capital of Puglia: an old town full of pasta-makers, a long seafront and the perfect base for exploring the south.', 'The bones of Saint Nicholas - the saint who inspired Santa Claus - were brought to Bari by sailors in 1087 and still rest in the Basilica di San Nicola.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 1, 'Bari Vecchia and "pasta street"', 'Watch the local women make orecchiette by hand outside their doors on Strada Arco Basso.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 2, 'Basilica di San Nicola', 'A beautiful Romanesque church and an important pilgrimage site for both Catholics and Orthodox Christians.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 3, 'Street food tour', 'Panzerotti, sgagliozze (fried polenta) and focaccia barese, fresh from the old town.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 4, 'Day trip to Polignano a Mare', 'White houses on cliffs above the sea and the famous Lama Monachile beach.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 5, 'Alberobello trulli', 'A fairy-tale town of white stone houses with cone-shaped roofs, a UNESCO site about an hour away.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1200&q=75', 'Old town of Bari', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'bari'), 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=75', 'Puglia coast', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'italy'), 'rome', 'Rome', 'The Eternal City: ancient ruins, Baroque fountains, the Vatican and long dinners in cobbled piazzas.', 'About 3,000 euros in coins are thrown into the Trevi Fountain every day. The money is collected and given to charity - and tradition says one coin means you will return to Rome.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 1, 'Colosseum and the Roman Forum', 'Walk where gladiators fought and senators spoke. Book timed tickets online in advance.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 2, 'Vatican Museums and the Sistine Chapel', 'Michelangelo''s ceiling and St Peter''s Basilica. Go early or late to avoid the longest queues.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 3, 'Trevi Fountain and the Pantheon at dawn', 'See them almost empty before the city wakes up, then espresso standing at the bar.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 4, 'Trastevere at night', 'Ivy-covered lanes, cacio e pepe and carbonara in a family trattoria.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 5, 'Borghese Gallery and gardens', 'Bernini sculptures inside, then a sunset view over the city from the Pincio terrace.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1200&q=75', 'Rome', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'rome'), 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=75', 'Roman streets', 1);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'italy'), 'pisa', 'Pisa', 'Much more than the famous tower: a lively university town on the Arno, close to Florence, Lucca and the Tuscan coast.', 'The tower started to lean during construction in the 12th century because of soft ground. Engineers reduced the lean by about 45 cm between 1990 and 2001, so it should stay standing for centuries.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1600&q=75', 4);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 1, 'Climb the Leaning Tower', 'Around 250 slightly tilted steps to the top. Tickets are timed, so book in advance.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 2, 'Piazza dei Miracoli', 'The white marble Cathedral, Baptistery and monumental cemetery around the tower, all on a green lawn.', 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 3, 'Walk along the Arno', 'The riverside "lungarni" at sunset, with colourful palaces and the tiny Gothic church of Santa Maria della Spina.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 4, 'Day trip to Lucca', 'Cycle on top of the Renaissance city walls, just 30 minutes away by train.', 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 5, 'Florence or the Tuscan coast', 'One hour to Florence''s art and food, or head to the beaches of Viareggio and the Cinque Terre.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 'https://images.unsplash.com/photo-1516483638261-f4dbaf036963?auto=format&fit=crop&w=1200&q=75', 'Piazza dei Miracoli', 0);
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'italy' AND p.slug = 'pisa'), 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1200&q=75', 'The Arno at sunset', 1);
INSERT INTO destination (slug, name, flag, region, vibes, tagline, description, best_time_to_visit, hero_image_url, lat, lng, sort_order) VALUES ('norway', 'Norway', '🇳🇴', 'Europe', 'Nature', 'Fjords, fishing villages and the Northern Lights.', 'Dramatic fjords, red cabins on the water and Arctic adventures above the polar circle. Norway is the place where you take a train through the mountains in the morning, kayak a fjord in the afternoon and wait for the sky to turn green at night.', 'June - August (fjords, hiking, midnight sun) and late September - March (Northern Lights)', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=75', 60.47, 8.47, 10);
INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'oslo', 'Oslo', 'A green, relaxed capital on the water, with world-class museums and saunas right on the fjord.', 'The Nobel Peace Prize is the only Nobel Prize awarded outside Sweden - it is presented every 10 December in Oslo City Hall.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=1600&q=75', 0);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 1, 'Walk on the Opera House roof', 'The sloping white marble roof rises straight out of the fjord - walk all the way to the top for sunset.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 2, 'Vigeland Sculpture Park', 'More than 200 sculptures by Gustav Vigeland in Frogner Park, free and open all day.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'oslo'), 3, 'MUNCH museum', 'Edvard Munch''s work, including versions of The Scream, in a striking building on the harbour.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
