INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'bergen-the-fjords', 'Bergen & the Fjords', 'The colourful Hanseatic port city and the gateway to Norway''s most famous fjords.', 'Bergen is one of the rainiest cities in Europe, with rain on more than 200 days a year - locals joke that babies here are born with umbrellas.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=75', 1);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 1, 'Bryggen wharf', 'Wander the narrow alleys behind the colourful wooden merchant houses, a UNESCO World Heritage site.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 2, 'Floibanen funicular to Mount Floyen', 'Ride up in minutes for the classic view over the city, then hike back down through the forest.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 3, 'Flam Railway and Naeroyfjord cruise', 'One of the steepest standard-gauge railways in the world, then a boat through one of its narrowest fjords.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 4, 'Hike Trolltunga (summer)', 'A long, tough day hike to the famous rock ledge hanging 700 m above Lake Ringedalsvatnet.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 5, 'Fish Market lunch', 'Fresh shrimp, king crab and fish soup right on the harbour.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'bergen-the-fjords'), 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=75', 'Fjord view', 0);
