INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'lofoten', 'Lofoten', 'Jagged peaks rising straight out of the sea, red fishing cabins and white-sand Arctic beaches.', 'Lofoten is above the Arctic Circle, yet thanks to the Gulf Stream its winters are much milder than other places that far north.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1600&q=75', 2);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 1, 'Reine and Hamnoy at golden hour', 'The postcard view of red cabins, still water and sharp peaks - best from the bridges.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 2, 'Hike Reinebringen', 'About 2,000 stone steps up for one of the most famous viewpoints in Norway.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 3, 'Sleep in a rorbu', 'A traditional fisherman''s cabin on stilts over the water.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 4, 'Arctic surfing at Unstad', 'Surf under the midnight sun or the Northern Lights, with a thick wetsuit.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 5, 'Lofotr Viking Museum', 'A reconstruction of the largest Viking longhouse ever found, with a Viking feast in summer.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO image (place_id, url, caption, sort_order) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'lofoten'), 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=75', 'Lofoten fishing village', 0);
