INSERT INTO place (destination_id, slug, name, description, fun_fact, hero_image_url, sort_order) VALUES ((SELECT id FROM destination WHERE slug = 'norway'), 'tromso', 'Tromso', 'The capital of the Arctic and one of the best bases in the world for seeing the Northern Lights.', 'In Tromso the sun does not rise at all from late November to mid-January (polar night), and it does not set from late May to late July (midnight sun).', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1600&q=75', 3);
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 1, 'Northern Lights chase', 'Small-group tours drive away from the clouds and city lights to find the aurora.', 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 2, 'Husky sledding', 'Drive your own team of dogs across snowy valleys.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 3, 'Fjellheisen cable car', 'Up to Storsteinen, 421 m above the city, for the view at sunset or under the aurora.', 'https://images.unsplash.com/photo-1601439678777-b2b3c56fa627?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 4, 'Whale watching (November - January)', 'Orcas and humpbacks follow the herring into the northern fjords in winter.', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=75');
INSERT INTO activity (place_id, rank_no, title, description, image_url) VALUES ((SELECT p.id FROM place p JOIN destination d ON d.id = p.destination_id WHERE d.slug = 'norway' AND p.slug = 'tromso'), 5, 'Reindeer and Sami culture', 'Feed reindeer and listen to joik songs and stories in a lavvu tent by the fire.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=800&q=75');
